std::array<float,4> fitLegacy(const Keys& ih,int points,bool modern,int bass,int treble){
    Fitter f;f.ih=ih;f.IHpts=points;f.mB1=1;f.mK1=12;f.mB4=1;f.mK4=10;
    const auto b=intervals[bass],t=intervals[treble];f.BassNoffset=b.g;f.TrebleNoffset=t.g;
    f.BassPosIHFactor=beta(b.q,modern)-1;f.BassNegIHFactor=beta(b.p,modern)-1;
    f.TreblePosIHFactor=beta(t.q,modern)-1;f.TrebleNegIHFactor=beta(t.p,modern)-1;
    f.BassCoffset=b.g&1?-1.955f:0;f.TrebleCoffset=t.g&1?-1.955f:0;
    f.FullAutoAdjust();return {f.mB1,f.mK1,f.mB4,f.mK4};
}
Keys legacySplit(const Keys& ih,std::array<float,4> p,int split,bool modern,int bass){
    Keys y=legacy(p[0],p[1],p[2],p[3]);auto interval=intervals[bass];
    if(split>0&&split<45)for(int n=split-1;n>=0;n--){float w=float(n+1)/split;
        float octave=y[n+12]+ih[n+12]*(beta(3,modern)-1)-ih[n]*(beta(6,modern)-1);
        float selected=(y[n+interval.g]+ih[n+interval.g]*(beta(interval.q,modern)-1))-ih[n]*(beta(interval.p,modern)-1);
        y[n]=(1-w)*selected+octave*w;
    }return y;
}
